function trustedEvidenceUrl(value,fallback){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='api.weather.gov'&&!u.username&&!u.password?u.href:fallback}catch{return fallback}}
const FAA='https://nasstatus.faa.gov/api/airport-status-information';
let upstreamActive=0;
async function get(url,json=true){const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password||!['nasstatus.faa.gov','api.weather.gov','api.open-meteo.com'].includes(u.hostname))throw Error('Unsupported provider');if(upstreamActive>=32)throw Error('Provider capacity reached; retry shortly');upstreamActive++;try{const r=await fetch(u,{redirect:'error',headers:{'User-Agent':'Routewatch travel prototype','Accept':json?'application/geo+json, application/json':'application/xml'},signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('Provider unavailable');const reader=r.body.getReader();let size=0;const chunks=[];while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>4000000){await reader.cancel();throw Error('Provider response exceeds limit')}chunks.push(value)}const bytes=new Uint8Array(size);let offset=0;for(const c of chunks){bytes.set(c,offset);offset+=c.length}const text=new TextDecoder().decode(bytes);return json?JSON.parse(text):text}finally{upstreamActive--}}

function clean(s){return s.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim()}
export function zonedEpoch(date,time,zone){if(!/^\d{4}-\d{2}-\d{2}$/.test(date||'')||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time||''))throw Error('Enter valid airport-local dates and times.');const target=Date.parse(date+'T'+time+':00Z');if(!Number.isFinite(target)||new Date(target).toISOString().slice(0,10)!==date)throw Error('Enter a valid date.');const formatter=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});const parts=t=>Object.fromEntries(formatter.formatToParts(new Date(t)).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));const match=t=>{const p=parts(t);return p.year+'-'+p.month+'-'+p.day===date&&p.hour+':'+p.minute===time};let epoch=target;for(let i=0;i<6;i++){const p=parts(epoch),observed=Date.parse(p.year+'-'+p.month+'-'+p.day+'T'+p.hour+':'+p.minute+':00Z');const delta=target-observed;if(!delta)break;epoch+=delta}if(!match(epoch))throw Error('That local time does not exist during a daylight-saving transition. Choose another time.');if(match(epoch-3600000)||match(epoch+3600000))throw Error('That local time occurs twice during a daylight-saving transition. Choose an unambiguous time.');return epoch}
function localDate(epoch,zone){return new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(epoch))}
export function normalizeLeg(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Enter a valid route.');const {origin,destination,date}=input;if(typeof origin!=='string'||typeof destination!=='string'||! /^[A-Z]{3}$/.test(origin)||! /^[A-Z]{3}$/.test(destination)||!Object.hasOwn(airports,origin)||!Object.hasOwn(airports,destination))throw Error('Choose supported three-letter airport codes.');if(!airports[origin]||!airports[destination]||origin===destination)throw Error('Choose two different supported airports.');const departureTime=input.departureTime||'10:00',arrivalDate=input.arrivalDate||date,arrivalTime=input.arrivalTime||'16:00';const departureEpoch=zonedEpoch(date,departureTime,airports[origin][3]),arrivalEpoch=zonedEpoch(arrivalDate,arrivalTime,airports[destination][3]);const today=localDate(Date.now(),airports[origin][3]);const destinationToday=localDate(Date.now(),airports[destination][3]);if(date<today||arrivalDate<destinationToday||departureEpoch-Date.now()>14*86400000||arrivalEpoch-Date.now()>15*86400000)throw Error('Choose dates from today through the next 14 days.');if(arrivalEpoch<=departureEpoch)throw Error('Arrival must be after departure, accounting for each airport’s time zone.');if(arrivalEpoch-departureEpoch>72*3600000)throw Error('Keep each leg’s planning window within 72 hours.');return {origin,destination,date,departureTime,arrivalDate,arrivalTime,departureEpoch,arrivalEpoch}}
