export function airportDistance(from,to){const a=airports[from],b=airports[to],rad=x=>x*Math.PI/180;const h=Math.sin(rad(b[1]-a[1])/2)**2+Math.cos(rad(a[1]))*Math.cos(rad(b[1]))*Math.sin(rad(b[2]-a[2])/2)**2;return 3958.8*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)))}
export function nearbyAirports(code,exclude){if(!airports[code])throw Error('Unknown airport');return Object.keys(airports).filter(k=>k!==code&&k!==exclude&&airports[k][6]&&airports[k][8]==='large_airport').map(k=>({code:k,miles:Math.round(airportDistance(code,k)*10)/10})).filter(a=>a.miles<=100).sort((a,b)=>a.miles-b.miles).slice(0,2)}
function memoGetter(){const memo=new Map();return (url,json=true)=>{const key=url+'|'+json;if(!memo.has(key))memo.set(key,get(url,json));return memo.get(key)}}
