export function validateItinerary(input){if(!Array.isArray(input.legs)||input.legs.length<1||input.legs.length>4)throw Error('Enter one to four travel legs.');const legs=input.legs.map(normalizeLeg);for(let i=1;i<legs.length;i++){if(legs[i-1].destination!==legs[i].origin)throw Error('Each leg must start at the preceding arrival airport.');if(legs[i].departureEpoch<legs[i-1].arrivalEpoch)throw Error('A connection cannot depart before the preceding arrival, accounting for local time zones.')}return legs}
