// Organization-scoped operations store. D1 in Workers; SQLite adapter in local development.
class OpsError extends Error{constructor(message,status=400){super(message);this.status=status}}
let operationsChecksActive=0;
const opsNow=()=>new Date().toISOString(),opsId=()=>crypto.randomUUID();
const stmt=(db,sql,...args)=>db.prepare(sql).bind(...args),rows=async(db,sql,...args)=>(await stmt(db,sql,...args).all()).results;
const textField=(v,max=120)=>{if(typeof v!=='string'||v.length>max||/[\x00-\x08\x0b\x0c\x0e-\x1f]/.test(v))throw new OpsError('Invalid text field.');return v.trim()};
const normalizedEmail=v=>{v=textField(v,254).toLowerCase();if(!/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(v))throw new OpsError('Enter a valid email address.');return v};
async function operationsJSON(response,max=64000){if(!response.ok)throw Error('Service unavailable');const reader=response.body.getReader();let size=0,chunks=[];while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>max){await reader.cancel();throw Error('Response size limit')}chunks.push(value)}return JSON.parse(await new Blob(chunks).text())}
let accessKeys;
function tokenPart(part){if(!/^[\w-]+$/.test(part)||part.length>16000)throw new OpsError('Invalid sign-in token.',401);return Uint8Array.from(atob(part.replaceAll('-','+').replaceAll('_','/')),c=>c.charCodeAt(0))}
export async function operationsActor(request,env){
 if(env.LOCAL_DEVELOPMENT===true&&['localhost','127.0.0.1'].includes(new URL(request.url).hostname))return {email:'local-operator@routewatch.local',org:'local',role:'admin',local:true};
 if(!env.ACCESS_TEAM_DOMAIN||!env.ACCESS_AUD||!env.TEAM_MEMBERS)throw new OpsError('Team access is not configured. Use local development or configure Cloudflare Access.',503);
 if(!/^[a-z0-9-]+\.cloudflareaccess\.com$/.test(env.ACCESS_TEAM_DOMAIN))throw new OpsError('Invalid access configuration.',503);
 try{const token=request.headers.get('Cf-Access-Jwt-Assertion')||'',parts=token.split('.');if(parts.length!==3)throw Error();const head=JSON.parse(new TextDecoder().decode(tokenPart(parts[0]))),claims=JSON.parse(new TextDecoder().decode(tokenPart(parts[1])));const issuer='https://'+env.ACCESS_TEAM_DOMAIN;if(head.alg!=='RS256'||claims.iss!==issuer||!Array.isArray(claims.aud)||!claims.aud.includes(env.ACCESS_AUD)||!Number.isFinite(claims.exp)||claims.exp*1000<=Date.now()||(claims.nbf&&claims.nbf*1000>Date.now()+30000)||typeof claims.email!=='string')throw Error();if(!accessKeys||accessKeys.issuer!==issuer||accessKeys.until<Date.now()){const response=await fetch(issuer+'/cdn-cgi/access/certs',{signal:AbortSignal.timeout(10000),redirect:'error'});accessKeys={issuer,until:Date.now()+300000,keys:(await operationsJSON(response)).keys}}const key=accessKeys.keys.find(k=>k.kid===head.kid&&k.kty==='RSA');if(!key)throw Error();const imported=await crypto.subtle.importKey('jwk',key,{name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'},false,['verify']);if(!await crypto.subtle.verify('RSASSA-PKCS1-v1_5',imported,tokenPart(parts[2]),new TextEncoder().encode(parts[0]+'.'+parts[1])))throw Error();const email=claims.email.toLowerCase(),membership=JSON.parse(env.TEAM_MEMBERS)[email];if(!membership||!['admin','operator','viewer'].includes(membership.role)||!membership.org)throw Error();return {email,org:String(membership.org),role:membership.role,local:false}}catch{throw new OpsError('Sign in with an authorized team account.',401)}
}
function mayWrite(actor){if(!['admin','operator'].includes(actor.role))throw new OpsError('Your role allows viewing only.',403)}
async function tripFor(db,actor,id){if(typeof id!=='string'||id.length>60)throw new OpsError('Invalid trip identifier.');const t=await stmt(db,'SELECT * FROM trips WHERE id=? AND org=?',id,actor.org).first();if(!t)throw new OpsError('Trip not found.',404);return t}
function actionStatement(db,t,actor,kind,detail){return stmt(db,'INSERT INTO actions(id,org,trip_id,actor,kind,detail,created) VALUES(?,?,?,?,?,?,?)',opsId(),t.org,t.id,actor,kind,JSON.stringify(detail),opsNow())}
export function monitoringChange(before,after){if(!before)return null;const reasons=[];if(after.level>before.level)reasons.push('Risk classification increased: '+before.verdict+' → '+after.verdict);const key=e=>[e.source,e.airport,e.title,e.onset||(e.source==='FAA'?(e.advisoryType||'')+'|'+(e.advisoryReason||e.text||'').replace(/\b\d+(?:\.\d+)?\b/g,'#'):'')].join('|'),old=new Set(before.evidence.filter(e=>e.level>0&&['NWS','FAA'].includes(e.source)).map(key));for(const e of after.evidence.filter(e=>e.level>0&&['NWS','FAA'].includes(e.source)))if(!old.has(key(e)))reasons.push('New advisory: '+e.airport+' · '+e.title);return reasons.length?{reasons,missing:after.missing}:null}
async function enqueueTrip(db,env,t,force=false){if(t.archived)throw new OpsError('Archived trips cannot be checked.');const now=Date.now();if(!force&&t.next_check>now)return false;const token=opsId();const result=await stmt(db,'UPDATE trips SET check_token=?,checking_until=?,check_error=NULL WHERE id=? AND org=? AND checking_until<?',token,now+180000,t.id,t.org,now).run();if(!result.meta.changes)return false;const job={org:t.org,id:t.id,token};if(env.ASSESSMENT_QUEUE){try{await env.ASSESSMENT_QUEUE.send(job)}catch{await stmt(db,'UPDATE trips SET checking_until=0,check_error=? WHERE id=? AND check_token=?','Queue unavailable; retry shortly.',t.id,token).run();throw new OpsError('Background queue unavailable.',503)}}else try{await runOperationsCheck(env,job)}catch(e){await stmt(db,'UPDATE trips SET checking_until=0,check_token=NULL,next_check=?,check_error=? WHERE id=? AND check_token=?',Date.now()+60000,'Assessment capacity reached; retry shortly.',t.id,token).run();throw e}return true}
