 const plan=JSON.parse(t.plan);if(plan.at(-1).arrivalEpoch<Date.now()){await db.batch([stmt(db,'UPDATE trips SET monitoring=0,checking_until=0,check_token=NULL,check_error=? WHERE id=? AND check_token=?','Travel window has ended; monitoring paused.',t.id,running),actionStatement(db,t,'scheduler','monitoring_ended',{})]);return}
 const result=await assessor({legs:plan}),id=opsId();if(JSON.stringify(result).length>2500000)throw Error('Assessment size limit');const previous=t.latest_id?await stmt(db,'SELECT payload FROM assessments WHERE id=? AND org=?',t.latest_id,t.org).first():null;const change=monitoringChange(previous?JSON.parse(previous.payload):null,result),now=opsNow();
 const updates=[stmt(db,'INSERT INTO assessments(id,org,trip_id,checked,level,missing,verdict,payload,summary) VALUES(?,?,?,?,?,?,?,?,?)',id,t.org,t.id,result.checked,result.level,result.missing,result.verdict,JSON.stringify(result),JSON.stringify(result.evidence.filter(e=>e.level>0).map(e=>({source:e.source,airport:e.airport,title:e.title,level:e.level})))),stmt(db,"UPDATE trips SET latest_id=?,next_check=?,checking_until=0,check_token=NULL,check_error=NULL,updated=?,workflow=CASE WHEN ?=1 THEN 'unreviewed' ELSE workflow END,version=version+1 WHERE id=? AND org=? AND check_token=?",id,Date.now()+900000,now,change?1:0,t.id,t.org,running),actionStatement(db,t,'assessment-engine','assessment',{assessmentId:id,level:result.level,missing:result.missing,change:change?.reasons||[]})];
 if(change&&t.monitoring){const alert=opsId();updates.push(stmt(db,'INSERT INTO alerts(id,org,trip_id,assessment_id,reason,created) VALUES(?,?,?,?,?,?)',alert,t.org,t.id,id,JSON.stringify(change),now));for(const sub of await rows(db,'SELECT email FROM subscriptions WHERE org=? AND trip_id=?',t.org,t.id))updates.push(stmt(db,'INSERT INTO deliveries(id,org,alert_id,email) VALUES(?,?,?,?)',opsId(),t.org,alert,sub.email))}
