export async function deliverOperationsAlerts(env,transport=fetch){if(!env.DB||!env.RESEND_API_KEY||!env.ALERT_FROM)return {configured:false};const db=env.DB,now=Date.now();const pending=await rows(db,"SELECT d.*,a.reason,a.created,t.label,t.latest_id FROM deliveries d JOIN alerts a ON a.id=d.alert_id JOIN trips t ON t.id=a.trip_id WHERE d.status IN ('pending','failed') AND d.attempts<5 AND d.next_try<=? AND d.lease_until<? ORDER BY a.created LIMIT 10",now,now);for(const d of pending){const claim=await stmt(db,"UPDATE deliveries SET lease_until=?,attempts=attempts+1 WHERE id=? AND lease_until<? AND status IN ('pending','failed')",now+60000,d.id,now).run();if(!claim.meta.changes)continue;try{const active=await stmt(db,'SELECT s.email FROM subscriptions s JOIN alerts a ON s.trip_id=a.trip_id AND s.org=a.org WHERE a.id=? AND s.email=?',d.alert_id,d.email).first();const notificationTrip=await stmt(db,'SELECT t.monitoring,t.archived FROM trips t JOIN alerts a ON a.trip_id=t.id WHERE a.id=?',d.alert_id).first();if(!active||!notificationTrip?.monitoring||notificationTrip.archived){await stmt(db,"UPDATE deliveries SET status='cancelled',lease_until=0 WHERE id=?",d.id).run();continue}const reason=JSON.parse(d.reason);const source=await stmt(db,'SELECT payload FROM assessments WHERE id=(SELECT assessment_id FROM alerts WHERE id=?)',d.alert_id).first();const r=source?JSON.parse(source.payload):null;const evidence=(r?.evidence||[]).filter(e=>e.level>0).slice(0,3).map(e=>e.source+' / '+e.airport+' / '+e.title+'\n'+e.url).join('\n\n');let link='';if(env.PUBLIC_BASE_URL){const u=new URL(env.PUBLIC_BASE_URL);if(u.protocol==='https:'&&!u.username&&!u.password){u.pathname='/';u.search='';u.hash='trip='+d.alert_id;const a=await stmt(db,'SELECT trip_id FROM alerts WHERE id=?',d.alert_id).first();u.hash='trip='+a.trip_id;link='\nOpen Mission Control (sign-in required): '+u.href}}
 const response=await transport('https://api.resend.com/emails',{method:'POST',redirect:'error',signal:AbortSignal.timeout(15000),headers:{Authorization:'Bearer '+env.RESEND_API_KEY,'Content-Type':'application/json','Idempotency-Key':'routewatch-'+d.id},body:JSON.stringify({from:env.ALERT_FROM,to:[d.email],subject:'RouteWatch: '+d.label+' needs review',text:'Evidence captured '+d.created+'\n'+reason.reasons.join('\n')+'\n\nSource gaps: '+reason.missing+'. These are screening signals, not confirmed flight cancellations.\n\n'+evidence+link})});const sent=await operationsJSON(response);if(typeof sent.id!=='string')throw Error();await stmt(db,"UPDATE deliveries SET status='accepted',provider_id=?,error=NULL,lease_until=0 WHERE id=?",sent.id,d.id).run()}catch{await stmt(db,"UPDATE deliveries SET status='failed',error=?,next_try=?,lease_until=0 WHERE id=?",'Email provider unavailable.',Date.now()+Math.min(3600000,60000*2**d.attempts),d.id).run()}}return {configured:true,attempted:pending.length}}
export async function scheduledOperations(env){if(!env.DB)return;const due=await rows(env.DB,'SELECT * FROM trips WHERE monitoring=1 AND archived=0 AND next_check<=? AND checking_until<? ORDER BY next_check LIMIT 50',Date.now(),Date.now());for(const t of due)try{await enqueueTrip(env.DB,env,t)}catch{console.error(JSON.stringify({event:'scheduled_trip_enqueue_failed'}))}await deliverOperationsAlerts(env)}
