 if(!read&&operation==='check'){const latest=t.latest_id?await stmt(db,'SELECT checked FROM assessments WHERE id=? AND org=?',t.latest_id,actor.org).first():null;if(latest&&Date.now()-Date.parse(latest.checked)<30000)throw new OpsError('Checked recently. Wait 30 seconds before rechecking.',429);const queued=await enqueueTrip(db,env,t,true);return Response.json({queued,background:!!env.ASSESSMENT_QUEUE},{status:queued?202:200})}
