export async function operationsFetch(request,env={}){const trace=opsId(),start=Date.now(),response=await operationsHandler(request,env,trace);const headers=new Headers(response.headers);headers.set('X-Request-Id',trace);console.info(JSON.stringify({event:'operations_request',requestId:trace,status:response.status,durationMs:Date.now()-start}));return new Response(response.body,{status:response.status,headers})}
export async function simulateDecisions(input){const plans=validateItinerary({legs:input.legs});const index=input.legIndex??0;if(!Number.isInteger(index)||index<0||index>=plans.length||!Array.isArray(input.options)||input.options.length<1||input.options.length>3)throw new OpsError('Choose one to three scenarios for a valid leg.');const cached=memoGetter();const baseline=await itinerary({legs:plans},()=>{},cached),options=[{label:'Original itinerary',assessment:baseline,original:true}];for(const option of input.options){try{if(!option||typeof option!=='object')throw Error();const legs=plans.map(l=>({...l})),original=legs[index],label=textField(option.label||'Scenario',80);if(option.airport){const changed=option.endpoint==='origin'?'origin':'destination';if(!Object.hasOwn(airports,option.airport)||airportDistance(original[changed],option.airport)>100)throw Error('Choose a supported airport within 100 straight-line miles.');legs[index][changed]=option.airport;if(index>0&&changed==='origin')legs[index-1].destination=option.airport;if(index<legs.length-1&&changed==='destination')legs[index+1].origin=option.airport}else{const epoch=zonedEpoch(option.date||original.date,option.departureTime,airports[original.origin][3]),delta=epoch-original.departureEpoch,arrival=original.arrivalEpoch+delta;legs[index].date=option.date||original.date;legs[index].departureTime=option.departureTime;legs[index].arrivalDate=localDate(arrival,airports[original.destination][3]);legs[index].arrivalTime=new Intl.DateTimeFormat('en-GB',{timeZone:airports[original.destination][3],hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(arrival));}const assessment=await itinerary({legs},()=>{},cached);options.push({label,assessment,improved:baseline.missing===0&&assessment.missing===0&&assessment.level<baseline.level})}catch(e){options.push({label:typeof option?.label==='string'?option.label.slice(0,80):'Scenario',unavailable:'This option has invalid timing, connection continuity, dates, or airport distance. Adjust the scenario and retry.'})}}return {baseline,options,checked:opsNow(),note:'Each scenario rechecks source evidence. Time shifts preserve the selected leg’s elapsed duration; adjacent connections must remain valid. These are planning assumptions, not available flights. Airport distances are straight-line. A lower signal requires complete source coverage.'}}

