function showAiResult(r){if(!$('aiState')||!r.ai?.length)return;$('aiBadge').textContent='INTERPRETED';$('aiState').textContent='✓ '+(mode==='live'?'Evidence interpretation complete':'Interpreting recorded evidence');const aligned=r.ai.filter(a=>a.agreement==='aligned').length,different=r.ai.filter(a=>a.agreement==='different').length,uncertain=r.ai.length-aligned-different;const agreement=different?'Mixed: AI differs on '+different+' signal'+(different>1?'s':'')+'. Inspect the source and timing.':uncertain?'Uncertain: '+aligned+' aligned; '+uncertain+' inconclusive.':'AI interpretation aligns with all '+aligned+' reviewed rule flags.';$('aiOutput').innerHTML=r.ai.map(a=>'<div class="ai-line"><span>'+esc(a.id+' · '+a.source+' · '+a.label.replace('-related travel disruption',' conditions'))+'</span><span>'+esc(a.agreement||'category only')+'</span></div>').join('')+'<div class="agreement"><b>'+esc(agreement)+'</b><br>Agreement concerns whether the evidence suggests a possible disruption. The model does not validate the severity level or predict cancellations.</div><p class="ai-checklist"><b>AI-selected checklist</b><br>'+esc(r.ai[0].label==='weather-related travel disruption'?'Review airline weather waivers, allow extra time for airport access, and protect tight connections.':r.ai[0].label==='airport operational disruption'?'Check the airport advisory and airline status; ask your airline about backup options if the advisory persists.':'Keep checking your airline before leaving. Absence of an AI signal does not override the source-based risk rules.')+'</p><p class="ai-note">Follow the source-based recommended action above. Class preference is not a calibrated travel probability.</p>'}
async function retrieve(input,onSource){const response=await fetch('/api/itinerary-stream',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});if(!response.ok)throw Error('Could not retrieve the assessment. Please try again.');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',result;function handle(line){if(!line.trim())return;const event=JSON.parse(line);if(event.type==='source')onSource(event.source);if(event.type==='result')result=event.result;if(event.type==='error')throw Error(event.error)}try{while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let end;while((end=buffer.indexOf('\n'))>=0){handle(buffer.slice(0,end));buffer=buffer.slice(end+1)}}buffer+=decoder.decode();if(buffer.trim())handle(buffer);if(!result)throw Error('The source checks ended without an assessment. Try again.');return result}finally{reader.releaseLock()}}
