 $('opsWorkflow').onsubmit=async e=>{e.preventDefault();try{await opsApi('trips/'+id+'/update',{version:t.version,owner:$('opsOwner').value,workflow:$('opsWorkflowStatus').value,decision:$('opsDecision').value,monitoring:$('opsMonitoring').checked,archived:$('opsArchived').checked});await refresh()}catch(err){feedback(err.message)}};
