const tourSteps=[['missionStats','Company-wide status','Start with upcoming trips, elevated signals, review needs and source gaps. These counts come from stored assessments.'],['fleetTable','The trips that need attention','Your saved employee trips are sorted by risk. Open one to inspect evidence, assign an operator and record a decision.'],['attentionQueue','Act when conditions change','Monitoring creates alerts for risk increases and significant new advisories after a baseline check. Subscribe a recipient from a trip’s workflow.'],['riskAnalytics','Watch the portfolio evolve','Review latest signal distribution, advisory-affected airports and changes across stored checks.'],['planTrip','Explore the next decision','Plan a trip, inspect its evidence, ask Copilot, then compare departure windows in the decision simulator. Save it to Mission Control to monitor it.'],['missionControl','Try a real example','Use the sample trips below to explore complete, elevated and incomplete evidence. Their timestamps and capture limitations remain visible.']];
function finishTour(){document.querySelectorAll('.tour-target').forEach(el=>el.classList.remove('tour-target'));tourNode?.remove();tourNode=null;try{localStorage.setItem('routewatch.tour.v1','seen')}catch{}}
