document.querySelectorAll('[data-example]').forEach(b=>b.onclick=async()=>{try{$('sampleFeedback').textContent='Opening real recorded evidence…';const response=await fetch('/api/examples');if(!response.ok)throw Error('Recorded examples unavailable');const data=await response.json(),sample=data[b.dataset.example];if(!sample?.assessment)throw Error('This recorded example is unavailable.');openedOpsTrip=null;openRecorded(sample.assessment,'demo');$('opsOriginNote').textContent='Onboarding example · '+sample.description;finishTour()}catch(e){$('sampleFeedback').textContent=e.message}});
